/** The App with sign-in starter (stage 180, ADR 0190): Fieldnote, accounts and private notes in plain Node.js. */
export const MEMBERS_APP_FILES: StarterFile[] = [
  { path: ".env.example", content: "# Fieldnote's settings. None of these are secrets.\nPORT=3000\nDATA_DIR=data\n# Set to 1 behind a host's proxy (Render, Railway, Fly.io).\nTRUST_PROXY=0\n# Set to 1 to always mark cookies Secure.\nCOOKIE_SECURE=0\n" },
  { path: "DESIGN.md", content: "# DESIGN.md\n\nFieldnote is a quiet, private notebook: it should feel calm, fast and trustworthy, like a well-made tool rather than a marketing site. Replace this plan with your own product's before changing the look.\n\n## Palette\n\nLight only. A cool off-white canvas (#f6f7f9), white surfaces, near-black ink (#121722) with two softer inks for secondary text, and one accent: ink blue (#2346d8) for buttons and links. Red is only for deleting, green only for success messages. Every pair meets WCAG AA.\n\n## Type\n\nGeist from Google Fonts, falling back to the system's sans serif. Headlines are weight 500 with tight tracking; body text is 16px at 1.6 line height. No serif, no all-caps labels.\n\n## Layout\n\nA slim top bar with the name and the account links. Signed-out pages are one centred card, 40rem wide at most. The home page splits into the promise on the left and a labelled sample notebook on the right, then three plain lines on how accounts are kept safe. The notes page is a compose box above a list. Everything stacks into one column on a phone, with 44px targets and 16px inputs.\n\n## Signature\n\nThe sample notebook on the home page: a framed card of three real-looking notes with a small \"Sample\" tag, so people see what the app is for before they sign up.\n\n## Motion\n\nAlmost none: buttons press down a pixel, and colour changes take 150ms. Nothing moves under reduced motion.\n" },
  { path: "README.md", content: "# Fieldnote: an app with sign-in\n\nA members app in plain Node.js with no dependencies: people create an account, sign in, keep private notes, change their password, reset it by a one-time link, and delete their account. It's a starting point. Rename it, restyle it, and replace the notes with what your app is for.\n\nFieldnote, its copy and its sample notes are sample content.\n\n## Run it\n\n- `npm run dev` starts it on port 3000 and restarts on changes.\n- `npm test` starts it on a free port with its own data folder and uses it like a browser.\n- `npm start` runs it without watching.\n\nNothing is installed: it uses Node's own `http`, `crypto` and test runner (Node 22 or later).\n\nIn Farbaek's test space, open the preview in a **new tab** to sign in. Browsers keep sign-in cookies out of pages shown inside another site's frame.\n\n## How it keeps accounts safe\n\n- **Passwords:** stored as scrypt hashes with a random salt, never as typed. At least 12 characters.\n- **Sessions:**\n  - a random 32-byte token in an HttpOnly, SameSite=Lax cookie, Secure over https;\n  - the server keeps only its SHA-256;\n  - sessions last 14 days;\n  - changing or resetting a password signs out every other device.\n- **Forms:** every form carries a token. Signed-in forms use the session's own token; signed-out forms use a token that must match a cookie set with the page. A form posted from another site is refused.\n- **Sign-in:**\n  - a wrong email and a wrong password get the same answer, in the same time;\n  - tries are limited per network address and per email: 20 and 10 every 15 minutes.\n- **Password reset:** a one-time link that works for 30 minutes, kept as a hash. The page never says whether an email has an account.\n- **Notes:** belong to the account that wrote them. Nobody else can read or delete them, and everything shown is escaped.\n- **Headers:** a strict Content-Security-Policy, no framing, `nosniff` and a same-origin referrer.\n\n## Settings\n\nSee `.env.example`. None of them are secrets.\n\n| Setting | What it does |\n| --- | --- |\n| `PORT` | The port to listen on (3000 by default). |\n| `DATA_DIR` | Where the data file lives (`data` by default). |\n| `TRUST_PROXY=1` | Set it behind a host's proxy (Render, Railway, Fly.io), so limits count each visitor's own address. |\n| `COOKIE_SECURE=1` | Always mark cookies Secure. They already are when a request arrives over https. |\n\n## Keeping the data\n\nData is one JSON file in `DATA_DIR`, written whole and renamed into place, so a crash never leaves half a file.\n\n**Hosts wipe their disk on every deploy unless you attach one:** a disk on Render, a volume on Railway or on Fly.io. Point `DATA_DIR` at it. For more than a few hundred people, swap `src/store.js` for a database. The routes only call the functions it returns.\n\n## Sending reset links\n\nWithout an email service, a reset link is written to the server's log. To send it, replace `logResetLink` in `src/app.js` with a call to your email provider. Build the full link from your site's own address, never from the request's Host header.\n" },
  { path: "package.json", content: "{\n  \"name\": \"fieldnote\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"description\": \"A members app: accounts, sign-in and a private notebook for each person. Plain Node.js, no dependencies.\",\n  \"engines\": { \"node\": \">=22\" },\n  \"scripts\": {\n    \"dev\": \"node --watch src/server.js\",\n    \"start\": \"node src/server.js\",\n    \"test\": \"node --test\"\n  }\n}\n" },
  { path: "public/styles.css", content: "/* Fieldnote: light, quiet and readable. One accent (ink blue), pill buttons,\n   12px inputs and 20px cards. Change the tokens to make it yours. */\n:root {\n  --canvas: #f6f7f9;\n  --surface: #ffffff;\n  --ink: #121722;\n  --ink-2: #3d4554;\n  --ink-3: #5f6878;\n  --line: #e2e5eb;\n  --line-strong: #c9ced8;\n  --accent: #2346d8;\n  --accent-ink: #ffffff;\n  --danger: #b42318;\n  --ok: #157f3b;\n  --radius-card: 20px;\n  --radius-input: 12px;\n  --shadow: 0 1px 2px rgb(18 23 34 / 0.06), 0 8px 24px rgb(18 23 34 / 0.06);\n  --font: \"Geist\", ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml { -webkit-text-size-adjust: 100%; }\nbody {\n  margin: 0;\n  min-height: 100dvh;\n  display: flex;\n  flex-direction: column;\n  background: var(--canvas);\n  color: var(--ink);\n  font: 400 1rem/1.6 var(--font);\n}\na { color: var(--accent); text-underline-offset: 3px; }\na:hover { text-decoration-thickness: 2px; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n\n.top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  padding: 0.75rem clamp(1rem, 4vw, 2.5rem);\n  border-bottom: 1px solid var(--line);\n  background: var(--surface);\n}\n.brand { display: inline-flex; align-items: center; gap: 0.6rem; min-height: 44px; color: var(--ink); font-weight: 600; letter-spacing: -0.02em; text-decoration: none; }\n.mark { width: 22px; height: 22px; border-radius: 7px; background: linear-gradient(135deg, var(--accent), #6f86ff); }\n.nav { display: flex; align-items: center; gap: 1.25rem; flex-wrap: wrap; }\n.nav a, .nav .link { display: inline-flex; align-items: center; min-height: 44px; color: var(--ink-2); font-weight: 500; text-decoration: none; }\n.nav a:hover, .nav .link:hover { color: var(--ink); }\n.nav form { margin: 0; }\n\nmain { flex: 1; width: 100%; margin: 0 auto; padding: clamp(2rem, 6vw, 4.5rem) clamp(1rem, 4vw, 2.5rem); }\nmain.narrow { max-width: 40rem; }\nmain.wide { max-width: 72rem; }\n\nh1 { margin: 0 0 0.5rem; font-size: clamp(1.75rem, 1.2rem + 2vw, 2.5rem); line-height: 1.1; font-weight: 500; letter-spacing: -0.03em; }\nh2 { margin: 0 0 0.25rem; font-size: 1.125rem; font-weight: 500; letter-spacing: -0.01em; }\np { margin: 0 0 1rem; }\n.muted { color: var(--ink-3); }\n\n.button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 48px;\n  padding: 0 1.4rem;\n  border: 1px solid var(--accent);\n  border-radius: 999px;\n  background: var(--accent);\n  color: var(--accent-ink);\n  font: 500 1rem var(--font);\n  text-decoration: none;\n  cursor: pointer;\n  transition: transform 120ms ease-out, background-color 150ms ease-out;\n}\n.button:hover { background: #1b39b8; }\n.button:active { transform: translateY(1px); }\n.button.small { min-height: 40px; padding: 0 1rem; color: var(--accent-ink); }\n.button.ghost { background: transparent; color: var(--accent); }\n.button.ghost:hover { background: rgb(35 70 216 / 0.06); }\n.button.danger { background: var(--danger); border-color: var(--danger); }\n.link { border: 0; background: none; padding: 0; font: inherit; color: var(--accent); cursor: pointer; }\n.link.danger { color: var(--danger); min-height: 44px; }\n\n.card { padding: clamp(1.25rem, 4vw, 2rem); border: 1px solid var(--line); border-radius: var(--radius-card); background: var(--surface); box-shadow: var(--shadow); }\n.card.flat { box-shadow: none; margin-top: 1.25rem; }\n.danger-zone { border-color: rgb(180 35 24 / 0.3); }\n\n.stack { display: grid; gap: 1rem; margin-top: 1rem; }\n.field { display: grid; gap: 0.35rem; }\n.field span { font-size: 0.875rem; font-weight: 500; color: var(--ink-2); }\n.field small { color: var(--ink-3); font-size: 0.8125rem; }\ninput, textarea {\n  width: 100%;\n  min-height: 48px;\n  padding: 0.7rem 0.9rem;\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius-input);\n  background: var(--surface);\n  color: var(--ink);\n  font: 400 1rem/1.5 var(--font);\n}\ntextarea { resize: vertical; }\ninput:focus, textarea:focus { border-color: var(--accent); outline: 2px solid rgb(35 70 216 / 0.2); outline-offset: 0; }\n\n.alert, .notice { margin: 1rem 0 0; padding: 0.75rem 1rem; border-radius: var(--radius-input); font-size: 0.9375rem; }\n.alert { border: 1px solid rgb(180 35 24 / 0.35); background: rgb(180 35 24 / 0.06); color: var(--danger); }\n.notice { border: 1px solid rgb(21 127 59 / 0.35); background: rgb(21 127 59 / 0.06); color: var(--ok); }\n\n.hero { display: grid; grid-template-columns: 1fr; gap: 2.5rem; align-items: center; }\n.hero-copy p { font-size: 1.125rem; color: var(--ink-2); max-width: 34rem; }\n.hero h1 { font-size: clamp(2.25rem, 1.4rem + 3.6vw, 3.75rem); max-width: 14ch; }\n.actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 1.5rem; }\n.preview { position: relative; margin: 0; padding: 1.25rem; border: 1px solid var(--line); border-radius: 28px; background: var(--surface); box-shadow: var(--shadow); }\n.preview figcaption { position: absolute; top: -0.75rem; right: 1.25rem; padding: 0.1rem 0.7rem; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--ink-3); font-size: 0.75rem; }\n.preview ul, .notes { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.75rem; }\n.preview li { display: grid; gap: 0.15rem; padding: 0.9rem 1rem; border: 1px solid var(--line); border-radius: 14px; }\n.preview li span { color: var(--ink-3); font-size: 0.9375rem; }\n.facts { display: grid; gap: 0.5rem 2rem; margin-top: 3.5rem; padding-top: 2rem; border-top: 1px solid var(--line); color: var(--ink-2); }\n\n.compose { display: grid; gap: 0.75rem; margin: 1.5rem 0 2rem; padding: 1.25rem; border: 1px solid var(--line); border-radius: var(--radius-card); background: var(--surface); }\n.compose .button { justify-self: start; }\n.notes li { padding: 1rem 1.25rem; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); }\n.notes p { margin: 0 0 0.5rem; white-space: pre-wrap; overflow-wrap: anywhere; }\n.row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; color: var(--ink-3); font-size: 0.875rem; }\n.row form { margin: 0; }\n.empty { padding: 2rem; border: 1px dashed var(--line-strong); border-radius: var(--radius-card); color: var(--ink-3); text-align: center; }\n\n.foot { padding: 1.5rem clamp(1rem, 4vw, 2.5rem); border-top: 1px solid var(--line); color: var(--ink-3); font-size: 0.875rem; }\n.foot p { margin: 0; max-width: 72rem; }\n\n@media (min-width: 52rem) {\n  .hero { grid-template-columns: 1.1fr 0.9fr; }\n  .facts { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .button { transition: none; }\n}\n" },
  { path: "src/app.js", content: "// The routes. Pages are rendered on the server; every change is a form POST\n// that carries a token proving it came from this site. Sessions are a\n// random token in an HttpOnly cookie, kept on the server only as a hash.\nimport { readFile } from \"node:fs/promises\";\nimport { DECOY_HASH, createLimiter, hashPassword, newToken, normalizeEmail, passwordProblem, sameText, sha256, verifyPassword } from \"./auth.js\";\nimport * as view from \"./views.js\";\n\nconst SESSION_MS = 14 * 24 * 60 * 60 * 1000;\nconst RESET_MS = 30 * 60 * 1000;\nconst MAX_BODY = 16 * 1024;\nconst NOTE_MAX = 2000;\nconst STYLES = await readFile(new URL(\"../public/styles.css\", import.meta.url), \"utf8\");\n\nconst SECURITY_HEADERS = {\n  \"content-security-policy\":\n    \"default-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'\",\n  \"x-content-type-options\": \"nosniff\",\n  \"referrer-policy\": \"same-origin\",\n  \"x-frame-options\": \"DENY\",\n  \"permissions-policy\": \"camera=(), microphone=(), geolocation=()\",\n};\n\n/** Until an email service is connected, reset links go to the server's log. Swap this for your email provider. */\nfunction logResetLink(email, path) {\n  console.log(\"Password reset for \" + email + \": open \" + path + \" on this site. It works once, for 30 minutes.\");\n}\n\nexport function createApp({ store, sendResetLink = logResetLink }) {\n  const limits = {\n    signInByAddress: createLimiter(20, 15 * 60_000),\n    signInByEmail: createLimiter(10, 15 * 60_000),\n    signUp: createLimiter(10, 60 * 60_000),\n    reset: createLimiter(5, 60 * 60_000),\n    writes: createLimiter(120, 60_000),\n  };\n\n  return async function handle(req, res) {\n    try {\n      await route(req, res);\n    } catch (error) {\n      console.error(error);\n      if (!res.headersSent) send(res, 500, view.refused(\"Something went wrong on the server. Nothing was changed. Try again.\"));\n      else res.end();\n    }\n  };\n\n  async function route(req, res) {\n    const url = new URL(req.url, \"http://local\");\n    const path = url.pathname;\n    const method = req.method;\n\n    if (path === \"/health\") return json(res, 200, { ok: true });\n    if (path === \"/styles.css\") {\n      res.writeHead(200, { \"content-type\": \"text/css; charset=utf-8\", \"cache-control\": \"public, max-age=3600\", \"x-content-type-options\": \"nosniff\" });\n      return res.end(STYLES);\n    }\n\n    // A change must come from this site's own pages.\n    if (method === \"POST\" && !sameOrigin(req)) return send(res, 403, view.refused(\"That form didn't come from this site.\"));\n    const session = currentSession(req);\n    const user = session ? store.findUser(session.userId) : null;\n    const form = method === \"POST\" ? await readForm(req, res) : null;\n    if (method === \"POST\" && form === null) return;\n\n    // Signed-out forms carry a token that matches a cookie set with the page (double submit).\n    const pre = cookies(req).pre || null;\n    const preToken = () => pre || setPreToken(req, res);\n    const preOk = () => Boolean(pre) && sameText(form?._csrf ?? \"\", pre);\n    // Signed-in forms carry the session's own token.\n    const csrfOk = () => Boolean(session) && sameText(form?._csrf ?? \"\", session.csrf);\n\n    if (method === \"GET\" && path === \"/\") return user ? redirect(res, \"/app\") : send(res, 200, view.home());\n\n    if (path === \"/sign-up\") {\n      if (user) return redirect(res, \"/app\");\n      if (method === \"GET\") return send(res, 200, view.signUp({ csrf: preToken() }));\n      if (!preOk()) return send(res, 403, view.refused(\"This form expired. Go back, reload the page and try again.\"));\n      if (!limits.signUp(address(req))) return send(res, 429, view.signUp({ csrf: preToken(), error: \"Too many new accounts from your network. Try again in an hour.\", values: form }));\n      const name = String(form.name ?? \"\").trim().slice(0, 80);\n      const email = normalizeEmail(form.email);\n      const problem = !name ? \"Tell us your name.\" : !email ? \"That email address doesn't look right.\" : passwordProblem(form.password);\n      if (problem) return send(res, 400, view.signUp({ csrf: preToken(), error: problem, values: { name, email: form.email } }));\n      if (store.findUserByEmail(email)) return send(res, 409, view.signUp({ csrf: preToken(), error: \"That email already has an account. Sign in, or reset its password.\", values: { name, email } }));\n      const created = await store.createUser({ email, name, passwordHash: await hashPassword(form.password) });\n      await startSession(req, res, created.id);\n      return redirect(res, \"/app\");\n    }\n\n    if (path === \"/sign-in\") {\n      if (user) return redirect(res, \"/app\");\n      if (method === \"GET\") return send(res, 200, view.signIn({ csrf: preToken(), message: url.searchParams.get(\"done\") === \"deleted\" ? \"Your account and its notes were deleted.\" : null }));\n      if (!preOk()) return send(res, 403, view.refused(\"This form expired. Go back, reload the page and try again.\"));\n      const email = normalizeEmail(form.email);\n      if (!limits.signInByAddress(address(req)) || (email && !limits.signInByEmail(email))) {\n        return send(res, 429, view.signIn({ csrf: preToken(), error: \"Too many tries. Wait 15 minutes, then try again.\", values: { email: form.email } }));\n      }\n      const found = email ? store.findUserByEmail(email) : null;\n      // The same work whether or not the email has an account, so the answer's timing gives nothing away.\n      const valid = await verifyPassword(String(form.password ?? \"\"), found ? found.passwordHash : DECOY_HASH);\n      if (!found || !valid) return send(res, 401, view.signIn({ csrf: preToken(), error: \"That email and password don't match an account.\", values: { email: form.email } }));\n      await startSession(req, res, found.id);\n      return redirect(res, \"/app\");\n    }\n\n    if (path === \"/reset\") {\n      if (method === \"GET\") return send(res, 200, view.resetRequest({ csrf: preToken() }));\n      if (!preOk()) return send(res, 403, view.refused(\"This form expired. Go back, reload the page and try again.\"));\n      if (!limits.reset(address(req))) return send(res, 429, view.resetRequest({ csrf: preToken(), error: \"Too many reset requests from your network. Try again in an hour.\" }));\n      const email = normalizeEmail(form.email);\n      const found = email ? store.findUserByEmail(email) : null;\n      if (found) {\n        const token = newToken();\n        await store.addReset({ hash: sha256(token), userId: found.id, expiresAt: Date.now() + RESET_MS });\n        await sendResetLink(found.email, \"/reset/\" + token);\n      }\n      // The same answer either way, so the page doesn't say who has an account.\n      return send(res, 200, view.resetRequest({ sent: true }));\n    }\n\n    const reset = path.match(/^\\/reset\\/([A-Za-z0-9_-]{43})$/);\n    if (reset) {\n      const token = reset[1];\n      if (method === \"GET\") return send(res, 200, view.resetForm({ csrf: preToken(), token }));\n      if (!preOk()) return send(res, 403, view.refused(\"This form expired. Go back, reload the page and try again.\"));\n      const problem = passwordProblem(form.password);\n      if (problem) return send(res, 400, view.resetForm({ csrf: preToken(), token, error: problem }));\n      const taken = await store.takeReset(sha256(token));\n      if (!taken || !store.findUser(taken.userId)) return send(res, 400, view.resetForm({ csrf: preToken(), token, error: \"This link has expired or was already used. Ask for a new one.\" }));\n      await store.setPassword(taken.userId, await hashPassword(form.password));\n      await store.removeSessionsFor(taken.userId);\n      await startSession(req, res, taken.userId);\n      return redirect(res, \"/app\");\n    }\n\n    // Everything below is for signed-in people only.\n    if (!user) {\n      if (path === \"/app\" || path.startsWith(\"/app/\") || path === \"/account\" || path.startsWith(\"/account/\") || path === \"/sign-out\") return redirect(res, \"/sign-in\");\n      return send(res, 404, view.notFound(null, null));\n    }\n    if (method === \"POST\" && !csrfOk()) return send(res, 403, view.refused(\"This form expired. Go back, reload the page and try again.\"));\n    if (method === \"POST\" && !limits.writes(user.id)) return send(res, 429, view.refused(\"Too many changes in a minute. Wait a moment, then try again.\"));\n\n    if (path === \"/sign-out\" && method === \"POST\") {\n      await store.removeSession(session.hash);\n      clearSession(req, res);\n      return redirect(res, \"/\");\n    }\n\n    if (path === \"/app\" && method === \"GET\") return send(res, 200, view.notes({ user, csrf: session.csrf, list: store.notesFor(user.id) }));\n\n    if (path === \"/app/notes\" && method === \"POST\") {\n      const text = String(form.text ?? \"\").trim();\n      if (!text || text.length > NOTE_MAX) {\n        return send(res, 400, view.notes({ user, csrf: session.csrf, list: store.notesFor(user.id), error: \"Write between 1 and \" + NOTE_MAX + \" characters.\" }));\n      }\n      await store.addNote(user.id, text);\n      return redirect(res, \"/app\");\n    }\n\n    const del = path.match(/^\\/app\\/notes\\/([0-9a-f-]{36})\\/delete$/);\n    if (del && method === \"POST\") {\n      const deleted = await store.deleteNote(user.id, del[1]);\n      return deleted ? redirect(res, \"/app\") : send(res, 404, view.notFound(user, session.csrf));\n    }\n\n    if (path === \"/account\" && method === \"GET\") return send(res, 200, view.account({ user, csrf: session.csrf, message: url.searchParams.get(\"done\") === \"password\" ? \"Password changed. Every other device was signed out.\" : null }));\n\n    if (path === \"/account/password\" && method === \"POST\") {\n      if (!(await verifyPassword(String(form.current ?? \"\"), user.passwordHash))) return send(res, 400, view.account({ user, csrf: session.csrf, error: \"Your current password isn't right.\" }));\n      const problem = passwordProblem(form.password);\n      if (problem) return send(res, 400, view.account({ user, csrf: session.csrf, error: problem }));\n      await store.setPassword(user.id, await hashPassword(form.password));\n      await store.removeSessionsFor(user.id);\n      await startSession(req, res, user.id);\n      return redirect(res, \"/account?done=password\");\n    }\n\n    if (path === \"/account/delete\" && method === \"POST\") {\n      if (!(await verifyPassword(String(form.password ?? \"\"), user.passwordHash))) return send(res, 400, view.account({ user, csrf: session.csrf, error: \"That password isn't right, so nothing was deleted.\" }));\n      await store.deleteUser(user.id);\n      clearSession(req, res);\n      return redirect(res, \"/sign-in?done=deleted\");\n    }\n\n    return send(res, 404, view.notFound(user, session.csrf));\n  }\n\n  function currentSession(req) {\n    const sid = cookies(req).sid;\n    return sid && /^[A-Za-z0-9_-]{43}$/.test(sid) ? store.findSession(sha256(sid)) : null;\n  }\n\n  async function startSession(req, res, userId) {\n    const sid = newToken();\n    await store.addSession({ hash: sha256(sid), userId, csrf: newToken(), expiresAt: Date.now() + SESSION_MS });\n    setCookie(req, res, \"sid\", sid, { maxAge: SESSION_MS / 1000 });\n  }\n\n  function clearSession(req, res) {\n    setCookie(req, res, \"sid\", \"\", { maxAge: 0 });\n  }\n\n  function setPreToken(req, res) {\n    const token = newToken();\n    setCookie(req, res, \"pre\", token, { maxAge: 60 * 60, sameSite: \"Strict\" });\n    return token;\n  }\n}\n\n// ----------------------------------------------------------------- helpers\n\nfunction cookies(req) {\n  const out = {};\n  for (const part of String(req.headers.cookie ?? \"\").split(\";\")) {\n    const i = part.indexOf(\"=\");\n    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());\n  }\n  return out;\n}\n\n/** Secure cookies when the request arrived over https, directly or through the host's proxy. */\nfunction secure(req) {\n  return process.env.COOKIE_SECURE === \"1\" || req.headers[\"x-forwarded-proto\"] === \"https\" || Boolean(req.socket?.encrypted);\n}\n\nfunction setCookie(req, res, name, value, { maxAge, sameSite = \"Lax\" }) {\n  const cookie = name + \"=\" + encodeURIComponent(value) + \"; Path=/; HttpOnly; SameSite=\" + sameSite + \"; Max-Age=\" + Math.floor(maxAge) + (secure(req) ? \"; Secure\" : \"\");\n  const existing = res.getHeader(\"set-cookie\");\n  res.setHeader(\"set-cookie\", existing ? [].concat(existing, cookie) : [cookie]);\n}\n\n/** The client's network address. Behind a host's proxy, set TRUST_PROXY=1 so the first forwarded address is used. */\nfunction address(req) {\n  if (process.env.TRUST_PROXY === \"1\") {\n    const forwarded = String(req.headers[\"x-forwarded-for\"] ?? \"\").split(\",\")[0].trim();\n    if (forwarded) return forwarded;\n  }\n  return req.socket?.remoteAddress ?? \"unknown\";\n}\n\n/** A POST is accepted only from this site's own pages, when the browser says where it came from. */\nfunction sameOrigin(req) {\n  const origin = req.headers.origin;\n  if (!origin) return true;\n  try {\n    return new URL(origin).host === req.headers.host;\n  } catch {\n    return false;\n  }\n}\n\nasync function readForm(req, res) {\n  const type = String(req.headers[\"content-type\"] ?? \"\");\n  if (!type.startsWith(\"application/x-www-form-urlencoded\")) {\n    send(res, 415, view.refused(\"Send the form as it is on the page.\"));\n    return null;\n  }\n  let size = 0;\n  const chunks = [];\n  for await (const chunk of req) {\n    size += chunk.length;\n    if (size > MAX_BODY) {\n      send(res, 413, view.refused(\"That form was too large.\"));\n      return null;\n    }\n    chunks.push(chunk);\n  }\n  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString(\"utf8\")));\n}\n\nfunction send(res, status, html) {\n  res.writeHead(status, { \"content-type\": \"text/html; charset=utf-8\", \"cache-control\": \"no-store\", ...SECURITY_HEADERS });\n  res.end(html);\n}\n\nfunction json(res, status, body) {\n  res.writeHead(status, { \"content-type\": \"application/json; charset=utf-8\", \"cache-control\": \"no-store\" });\n  res.end(JSON.stringify(body));\n}\n\nfunction redirect(res, location) {\n  res.writeHead(303, { location, \"cache-control\": \"no-store\", ...SECURITY_HEADERS });\n  res.end();\n}\n" },
  { path: "src/auth.js", content: "// Passwords, tokens and limits, from Node's own crypto. Nothing here is\n// stored as it was typed: passwords are scrypt hashes, and session and reset\n// tokens are kept as SHA-256 hashes, so a copy of the data file opens nothing.\nimport { createHash, randomBytes, scrypt, timingSafeEqual } from \"node:crypto\";\n\nconst KEY_LENGTH = 64;\nconst COST = { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };\n\nfunction derive(password, salt, cost = COST) {\n  return new Promise((resolve, reject) => {\n    scrypt(password, salt, KEY_LENGTH, cost, (error, key) => (error ? reject(error) : resolve(key)));\n  });\n}\n\nexport async function hashPassword(password) {\n  const salt = randomBytes(16);\n  const key = await derive(password, salt);\n  return [\"scrypt\", COST.N, COST.r, COST.p, salt.toString(\"base64url\"), key.toString(\"base64url\")].join(\"$\");\n}\n\nexport async function verifyPassword(password, stored) {\n  const parts = typeof stored === \"string\" ? stored.split(\"$\") : [];\n  if (parts.length !== 6 || parts[0] !== \"scrypt\") return false;\n  const [, n, r, p, salt, key] = parts;\n  const expected = Buffer.from(key, \"base64url\");\n  const actual = await derive(password, Buffer.from(salt, \"base64url\"), { N: Number(n), r: Number(r), p: Number(p), maxmem: COST.maxmem });\n  return actual.length === expected.length && timingSafeEqual(actual, expected);\n}\n\n// Checked against when an email has no account, so a wrong email takes as long as a wrong password.\nexport const DECOY_HASH = \"scrypt$16384$8$1$AAAAAAAAAAAAAAAAAAAAAA$\" + \"A\".repeat(86);\n\n/** 32 random bytes as text: for sessions, reset links and form tokens. */\nexport const newToken = () => randomBytes(32).toString(\"base64url\");\nexport const sha256 = (text) => createHash(\"sha256\").update(text).digest(\"hex\");\n\n/** Two strings compared in the same time whatever they hold. */\nexport function sameText(a, b) {\n  const x = Buffer.from(String(a));\n  const y = Buffer.from(String(b));\n  return x.length === y.length && timingSafeEqual(x, y);\n}\n\n/** Lower case, trimmed, and plausibly an email address, or null. */\nexport function normalizeEmail(value) {\n  const email = String(value ?? \"\").trim().toLowerCase();\n  return email.length >= 3 && email.length <= 254 && /^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email) ? email : null;\n}\n\nexport const PASSWORD_MIN = 12;\nexport const PASSWORD_MAX = 200;\n\n/** Why a new password isn't accepted, or null. */\nexport function passwordProblem(password) {\n  if (typeof password !== \"string\" || password.length < PASSWORD_MIN) return \"Use at least \" + PASSWORD_MIN + \" characters.\";\n  if (password.length > PASSWORD_MAX) return \"Use at most \" + PASSWORD_MAX + \" characters.\";\n  return null;\n}\n\n/** A fixed-window counter kept in memory: true while a key is under its limit. */\nexport function createLimiter(limit, windowMs) {\n  const hits = new Map();\n  return function allow(key) {\n    const now = Date.now();\n    const hit = hits.get(key);\n    if (!hit || hit.resetAt <= now) {\n      hits.set(key, { count: 1, resetAt: now + windowMs });\n      if (hits.size > 10_000) for (const [k, v] of hits) if (v.resetAt <= now) hits.delete(k);\n      return true;\n    }\n    hit.count += 1;\n    return hit.count <= limit;\n  };\n}\n" },
  { path: "src/server.js", content: "// Starts the app. Reads --port and --hostname (Farbaek's preview passes them), then PORT, then 3000.\nimport { createServer } from \"node:http\";\nimport { createApp } from \"./app.js\";\nimport { createStore } from \"./store.js\";\n\nfunction flag(name, fallback) {\n  const i = process.argv.indexOf(\"--\" + name);\n  return i > -1 && process.argv[i + 1] ? process.argv[i + 1] : fallback;\n}\n\nconst port = Number(flag(\"port\", process.env.PORT || 3000));\nconst hostname = flag(\"hostname\", \"0.0.0.0\");\nconst store = await createStore(process.env.DATA_DIR || \"data\");\nconst server = createServer(createApp({ store }));\nserver.listen(port, hostname, () => {\n  console.log(\"Fieldnote on http://\" + hostname + \":\" + port + \" (data in \" + store.file + \")\");\n});\n" },
  { path: "src/store.js", content: "// Where the data lives: one JSON file, written whole to a temporary file and\n// renamed over the old one, so a crash never leaves half a file. Writes run\n// one after another. Swap this module for a database when you outgrow it:\n// the app only calls the functions returned here.\nimport { randomUUID } from \"node:crypto\";\nimport { mkdir, readFile, rename, writeFile } from \"node:fs/promises\";\nimport { join } from \"node:path\";\n\nconst EMPTY = () => ({ users: [], sessions: [], notes: [], resets: [] });\n\nexport async function createStore(dir) {\n  await mkdir(dir, { recursive: true });\n  const file = join(dir, \"fieldnote.json\");\n  let data = EMPTY();\n  try {\n    data = { ...EMPTY(), ...JSON.parse(await readFile(file, \"utf8\")) };\n  } catch (error) {\n    if (error.code !== \"ENOENT\") throw error;\n  }\n\n  let queue = Promise.resolve();\n  function save() {\n    const snapshot = JSON.stringify(data);\n    queue = queue.then(async () => {\n      const temp = file + \".\" + process.pid + \".tmp\";\n      await writeFile(temp, snapshot, { mode: 0o600 });\n      await rename(temp, file);\n    });\n    return queue;\n  }\n\n  const now = () => Date.now();\n  const live = (s) => s.expiresAt > now();\n\n  return {\n    file,\n\n    findUserByEmail: (email) => data.users.find((u) => u.email === email) ?? null,\n    findUser: (id) => data.users.find((u) => u.id === id) ?? null,\n    async createUser({ email, name, passwordHash }) {\n      const user = { id: randomUUID(), email, name, passwordHash, createdAt: new Date().toISOString() };\n      data.users.push(user);\n      await save();\n      return user;\n    },\n    async setPassword(userId, passwordHash) {\n      const user = data.users.find((u) => u.id === userId);\n      if (!user) return false;\n      user.passwordHash = passwordHash;\n      await save();\n      return true;\n    },\n    async deleteUser(userId) {\n      data.users = data.users.filter((u) => u.id !== userId);\n      data.sessions = data.sessions.filter((s) => s.userId !== userId);\n      data.notes = data.notes.filter((n) => n.userId !== userId);\n      data.resets = data.resets.filter((r) => r.userId !== userId);\n      await save();\n    },\n\n    async addSession(session) {\n      data.sessions = data.sessions.filter(live);\n      data.sessions.push(session);\n      await save();\n    },\n    findSession: (hash) => data.sessions.find((s) => s.hash === hash && live(s)) ?? null,\n    async removeSession(hash) {\n      data.sessions = data.sessions.filter((s) => s.hash !== hash);\n      await save();\n    },\n    async removeSessionsFor(userId) {\n      data.sessions = data.sessions.filter((s) => s.userId !== userId);\n      await save();\n    },\n\n    notesFor: (userId) => data.notes.filter((n) => n.userId === userId).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1)),\n    async addNote(userId, text) {\n      const note = { id: randomUUID(), userId, text, createdAt: new Date().toISOString() };\n      data.notes.push(note);\n      await save();\n      return note;\n    },\n    // Only the note's own author can delete it: the id alone is never enough.\n    async deleteNote(userId, noteId) {\n      const before = data.notes.length;\n      data.notes = data.notes.filter((n) => !(n.id === noteId && n.userId === userId));\n      if (data.notes.length === before) return false;\n      await save();\n      return true;\n    },\n\n    async addReset(reset) {\n      data.resets = data.resets.filter((r) => r.expiresAt > now() && r.userId !== reset.userId);\n      data.resets.push(reset);\n      await save();\n    },\n    // A reset link works once, before it expires.\n    async takeReset(hash) {\n      const reset = data.resets.find((r) => r.hash === hash);\n      if (!reset) return null;\n      data.resets = data.resets.filter((r) => r !== reset);\n      await save();\n      return reset.expiresAt > now() ? reset : null;\n    },\n  };\n}\n" },
  { path: "src/views.js", content: "// Every page, as HTML strings. Everything a person typed goes through esc(),\n// so nobody's note or name can run as code in someone else's browser.\nexport function esc(value) {\n  return String(value ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[c]);\n}\n\nconst date = (iso) => new Date(iso).toLocaleDateString(\"en-GB\", { day: \"numeric\", month: \"short\", year: \"numeric\" });\n\nfunction layout({ title, user, csrf, body, wide = false }) {\n  const nav = user\n    ? '<nav class=\"nav\" aria-label=\"Account\">' +\n      '<a href=\"/app\">Notes</a>' +\n      '<a href=\"/account\">Account</a>' +\n      '<form method=\"post\" action=\"/sign-out\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\"><button class=\"link\" type=\"submit\">Sign out</button></form>' +\n      \"</nav>\"\n    : '<nav class=\"nav\" aria-label=\"Account\"><a href=\"/sign-in\">Sign in</a><a class=\"button small\" href=\"/sign-up\">Create account</a></nav>';\n  return (\n    \"<!doctype html>\" +\n    '<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">' +\n    \"<title>\" + esc(title) + \" | Fieldnote</title>\" +\n    '<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>' +\n    '<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&display=swap\">' +\n    '<link rel=\"stylesheet\" href=\"/styles.css\"></head>' +\n    '<body><header class=\"top\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\"></span>Fieldnote</a>' + nav + \"</header>\" +\n    '<main id=\"main\" class=\"' + (wide ? \"wide\" : \"narrow\") + '\">' + body + \"</main>\" +\n    '<footer class=\"foot\"><p>Fieldnote is a sample app. Names, notes and accounts here are yours to replace.</p></footer>' +\n    \"</body></html>\"\n  );\n}\n\nfunction field({ label, name, type = \"text\", value = \"\", autocomplete, hint, required = true, minlength }) {\n  return (\n    '<label class=\"field\"><span>' + esc(label) + \"</span>\" +\n    '<input name=\"' + name + '\" type=\"' + type + '\" value=\"' + esc(value) + '\"' +\n    (autocomplete ? ' autocomplete=\"' + autocomplete + '\"' : \"\") +\n    (required ? \" required\" : \"\") +\n    (minlength ? ' minlength=\"' + minlength + '\"' : \"\") +\n    \">\" +\n    (hint ? '<small>' + esc(hint) + \"</small>\" : \"\") +\n    \"</label>\"\n  );\n}\n\nconst alert = (message) => (message ? '<p class=\"alert\" role=\"alert\">' + esc(message) + \"</p>\" : \"\");\nconst notice = (message) => (message ? '<p class=\"notice\" role=\"status\">' + esc(message) + \"</p>\" : \"\");\n\nexport function home() {\n  return layout({\n    title: \"Your notes, kept private\",\n    wide: true,\n    body:\n      '<section class=\"hero\">' +\n      '<div class=\"hero-copy\"><h1>Your notes, kept private.</h1>' +\n      \"<p>Write things down and find them again. Only you can read what you write: every note belongs to the account that wrote it.</p>\" +\n      '<div class=\"actions\"><a class=\"button\" href=\"/sign-up\">Create your account</a><a class=\"button ghost\" href=\"/sign-in\">Sign in</a></div></div>' +\n      '<figure class=\"preview\" aria-label=\"A sample notebook\">' +\n      '<figcaption>Sample</figcaption>' +\n      '<ul><li><strong>Thursday standup</strong><span>Ship the pricing page. Ask Ama about the import.</span></li>' +\n      \"<li><strong>Book list</strong><span>The Overstory. Piranesi. Klara and the Sun.</span></li>\" +\n      \"<li><strong>Kitchen</strong><span>Measure the window before ordering blinds.</span></li></ul></figure>\" +\n      \"</section>\" +\n      '<section class=\"facts\" aria-label=\"How it works\">' +\n      \"<p><strong>Passwords are never stored.</strong> Only a scrypt hash is kept.</p>\" +\n      \"<p><strong>Every form is protected.</strong> A token proves each change came from this site.</p>\" +\n      \"<p><strong>Your account is yours to delete,</strong> with every note in it.</p>\" +\n      \"</section>\",\n  });\n}\n\nexport function signUp({ csrf, error, values = {} }) {\n  return layout({\n    title: \"Create your account\",\n    body:\n      '<section class=\"card\"><h1>Create your account</h1>' + alert(error) +\n      '<form method=\"post\" action=\"/sign-up\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      field({ label: \"Name\", name: \"name\", value: values.name, autocomplete: \"name\" }) +\n      field({ label: \"Email\", name: \"email\", type: \"email\", value: values.email, autocomplete: \"email\" }) +\n      field({ label: \"Password\", name: \"password\", type: \"password\", autocomplete: \"new-password\", hint: \"At least 12 characters. A phrase is easiest to remember.\", minlength: 12 }) +\n      '<button class=\"button\" type=\"submit\">Create account</button></form>' +\n      '<p class=\"muted\">Have an account? <a href=\"/sign-in\">Sign in</a>.</p></section>',\n  });\n}\n\nexport function signIn({ csrf, error, message, values = {} }) {\n  return layout({\n    title: \"Sign in\",\n    body:\n      '<section class=\"card\"><h1>Sign in</h1>' + alert(error) + notice(message) +\n      '<form method=\"post\" action=\"/sign-in\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      field({ label: \"Email\", name: \"email\", type: \"email\", value: values.email, autocomplete: \"email\" }) +\n      field({ label: \"Password\", name: \"password\", type: \"password\", autocomplete: \"current-password\" }) +\n      '<button class=\"button\" type=\"submit\">Sign in</button></form>' +\n      '<p class=\"muted\"><a href=\"/reset\">Forgot your password?</a> New here? <a href=\"/sign-up\">Create an account</a>.</p></section>',\n  });\n}\n\nexport function resetRequest({ csrf, error, sent }) {\n  return layout({\n    title: \"Reset your password\",\n    body:\n      '<section class=\"card\"><h1>Reset your password</h1>' + alert(error) +\n      (sent\n        ? notice(\"If that email has an account, a reset link is on its way. It works once, for 30 minutes.\") +\n          '<p class=\"muted\">This sample app has no email service yet, so the link is written to the server\\'s log. Connect one in src/app.js (sendResetLink).</p>'\n        : '<form method=\"post\" action=\"/reset\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n          field({ label: \"Email\", name: \"email\", type: \"email\", autocomplete: \"email\" }) +\n          '<button class=\"button\" type=\"submit\">Send a reset link</button></form>') +\n      \"</section>\",\n  });\n}\n\nexport function resetForm({ csrf, token, error }) {\n  return layout({\n    title: \"Choose a new password\",\n    body:\n      '<section class=\"card\"><h1>Choose a new password</h1>' + alert(error) +\n      '<form method=\"post\" action=\"/reset/' + esc(token) + '\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      field({ label: \"New password\", name: \"password\", type: \"password\", autocomplete: \"new-password\", hint: \"At least 12 characters.\", minlength: 12 }) +\n      '<button class=\"button\" type=\"submit\">Save and sign in</button></form></section>',\n  });\n}\n\nexport function notes({ user, csrf, list, error }) {\n  const items = list.length\n    ? '<ul class=\"notes\">' +\n      list\n        .map(\n          (n) =>\n            '<li><p>' + esc(n.text) + \"</p>\" +\n            '<div class=\"row\"><time datetime=\"' + esc(n.createdAt) + '\">' + esc(date(n.createdAt)) + \"</time>\" +\n            '<form method=\"post\" action=\"/app/notes/' + esc(n.id) + '/delete\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n            '<button class=\"link danger\" type=\"submit\" aria-label=\"Delete this note\">Delete</button></form></div></li>',\n        )\n        .join(\"\") +\n      \"</ul>\"\n    : '<p class=\"empty\">No notes yet. Write the first one above: only you will see it.</p>';\n  return layout({\n    title: \"Your notes\",\n    user,\n    csrf,\n    body:\n      \"<h1>Your notes</h1>\" + '<p class=\"muted\">Signed in as ' + esc(user.email) + \". Nobody else can read these.</p>\" + alert(error) +\n      '<form method=\"post\" action=\"/app/notes\" class=\"compose\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      '<label class=\"field\"><span>New note</span><textarea name=\"text\" rows=\"3\" maxlength=\"2000\" required></textarea></label>' +\n      '<button class=\"button\" type=\"submit\">Save note</button></form>' + items,\n  });\n}\n\nexport function account({ user, csrf, error, message }) {\n  return layout({\n    title: \"Account\",\n    user,\n    csrf,\n    body:\n      \"<h1>Account</h1>\" + alert(error) + notice(message) +\n      '<section class=\"card flat\"><h2>' + esc(user.name) + \"</h2><p class=\\\"muted\\\">\" + esc(user.email) + \". Member since \" + esc(date(user.createdAt)) + \".</p></section>\" +\n      '<section class=\"card flat\"><h2>Change your password</h2>' +\n      '<form method=\"post\" action=\"/account/password\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      field({ label: \"Current password\", name: \"current\", type: \"password\", autocomplete: \"current-password\" }) +\n      field({ label: \"New password\", name: \"password\", type: \"password\", autocomplete: \"new-password\", hint: \"At least 12 characters. Every other device is signed out.\", minlength: 12 }) +\n      '<button class=\"button\" type=\"submit\">Change password</button></form></section>' +\n      '<section class=\"card flat danger-zone\"><h2>Delete your account</h2><p class=\"muted\">Your account and every note in it are deleted. This can\\'t be undone.</p>' +\n      '<form method=\"post\" action=\"/account/delete\" class=\"stack\"><input type=\"hidden\" name=\"_csrf\" value=\"' + esc(csrf) + '\">' +\n      field({ label: \"Password\", name: \"password\", type: \"password\", autocomplete: \"current-password\" }) +\n      '<button class=\"button danger\" type=\"submit\">Delete my account</button></form></section>',\n  });\n}\n\nexport function notFound(user, csrf) {\n  return layout({ title: \"Not found\", user, csrf, body: '<section class=\"card\"><h1>This page isn\\'t here</h1><p class=\"muted\"><a href=\"/\">Go to the start</a>.</p></section>' });\n}\n\nexport function refused(message) {\n  return layout({ title: \"Refused\", body: '<section class=\"card\"><h1>That didn\\'t go through</h1>' + alert(message) + '<p class=\"muted\"><a href=\"/\">Go to the start</a>.</p></section>' });\n}\n" },
  { path: "test/app.test.js", content: "// Starts the app on a free port with its own data folder and uses it like a browser would.\nimport assert from \"node:assert/strict\";\nimport { mkdtemp, readFile, rm } from \"node:fs/promises\";\nimport { createServer } from \"node:http\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { after, before, test } from \"node:test\";\nimport { createApp } from \"../src/app.js\";\nimport { createStore } from \"../src/store.js\";\n\nlet base = \"\";\nlet server;\nlet dir = \"\";\nconst resetLinks = [];\n\nbefore(async () => {\n  dir = await mkdtemp(join(tmpdir(), \"fieldnote-\"));\n  const store = await createStore(dir);\n  server = createServer(createApp({ store, sendResetLink: (email, path) => resetLinks.push({ email, path }) }));\n  await new Promise((resolve) => server.listen(0, \"127.0.0.1\", resolve));\n  base = \"http://127.0.0.1:\" + server.address().port;\n});\n\nafter(async () => {\n  await new Promise((resolve) => server.close(resolve));\n  await rm(dir, { recursive: true, force: true });\n});\n\n/** A browser with its own cookies. */\nfunction browser() {\n  const jar = new Map();\n  async function go(path, { method = \"GET\", form } = {}) {\n    const headers = { cookie: [...jar].map(([k, v]) => k + \"=\" + v).join(\"; \") };\n    if (form) headers[\"content-type\"] = \"application/x-www-form-urlencoded\";\n    const res = await fetch(base + path, { method, headers, body: form ? new URLSearchParams(form).toString() : undefined, redirect: \"manual\" });\n    for (const line of res.headers.getSetCookie()) {\n      const [pair] = line.split(\";\");\n      const i = pair.indexOf(\"=\");\n      const value = pair.slice(i + 1);\n      if (value === \"\") jar.delete(pair.slice(0, i));\n      else jar.set(pair.slice(0, i), value);\n    }\n    return { status: res.status, location: res.headers.get(\"location\"), html: await res.text(), headers: res.headers };\n  }\n  const token = (html) => html.match(/name=\"_csrf\" value=\"([^\"]+)\"/)?.[1] ?? \"\";\n  return {\n    go,\n    token,\n    async signUp(email, password = \"correct horse battery\", name = \"Ama\") {\n      const page = await go(\"/sign-up\");\n      return go(\"/sign-up\", { method: \"POST\", form: { _csrf: token(page.html), name, email, password } });\n    },\n    async signIn(email, password) {\n      const page = await go(\"/sign-in\");\n      return go(\"/sign-in\", { method: \"POST\", form: { _csrf: token(page.html), email, password } });\n    },\n    async addNote(text) {\n      const page = await go(\"/app\");\n      return go(\"/app/notes\", { method: \"POST\", form: { _csrf: token(page.html), text } });\n    },\n  };\n}\n\ntest(\"answers its health check and serves its own security headers\", async () => {\n  const res = await fetch(base + \"/health\");\n  assert.deepEqual(await res.json(), { ok: true });\n  const page = await fetch(base + \"/\");\n  assert.match(page.headers.get(\"content-security-policy\"), /frame-ancestors 'none'/);\n  assert.equal(page.headers.get(\"x-content-type-options\"), \"nosniff\");\n});\n\ntest(\"signs up, keeps the person signed in, and never stores the password\", async () => {\n  const a = browser();\n  const created = await a.signUp(\"ama@example.com\");\n  assert.equal(created.status, 303);\n  assert.equal(created.location, \"/app\");\n  const notes = await a.go(\"/app\");\n  assert.equal(notes.status, 200);\n  assert.match(notes.html, /Signed in as ama@example\\.com/);\n  const saved = await readFile(join(dir, \"fieldnote.json\"), \"utf8\");\n  assert.doesNotMatch(saved, /correct horse battery/);\n  assert.match(saved, /scrypt\\$16384/);\n});\n\ntest(\"refuses a form without its token, and a form from another site\", async () => {\n  const a = browser();\n  await a.signUp(\"kofi@example.com\");\n  const missing = await a.go(\"/app/notes\", { method: \"POST\", form: { text: \"planted\" } });\n  assert.equal(missing.status, 403);\n  const page = await a.go(\"/app\");\n  const res = await fetch(base + \"/app/notes\", {\n    method: \"POST\",\n    headers: { origin: \"https://evil.example\", \"content-type\": \"application/x-www-form-urlencoded\", cookie: \"\" },\n    body: new URLSearchParams({ _csrf: a.token(page.html), text: \"x\" }).toString(),\n    redirect: \"manual\",\n  });\n  assert.equal(res.status, 403);\n});\n\ntest(\"gives the same answer for a wrong password and an unknown email, then stops guesses\", async () => {\n  const a = browser();\n  await a.signUp(\"lena@example.com\");\n  const b = browser();\n  const wrong = await b.signIn(\"lena@example.com\", \"not the password at all\");\n  const unknown = await b.signIn(\"nobody@example.com\", \"not the password at all\");\n  assert.equal(wrong.status, 401);\n  assert.equal(unknown.status, 401);\n  assert.match(wrong.html, /don&#39;t match an account/);\n  assert.match(unknown.html, /don&#39;t match an account/);\n  let last;\n  for (let i = 0; i < 10; i += 1) last = await b.signIn(\"lena@example.com\", \"still wrong guess \" + i);\n  assert.equal(last.status, 429);\n});\n\ntest(\"keeps each person's notes to themselves\", async () => {\n  const a = browser();\n  await a.signUp(\"owner@example.com\");\n  await a.addNote(\"Only mine: <script>alert(1)</script>\");\n  const mine = await a.go(\"/app\");\n  assert.match(mine.html, /Only mine: &lt;script&gt;/);\n  const id = mine.html.match(/\\/app\\/notes\\/([0-9a-f-]{36})\\/delete/)[1];\n\n  const b = browser();\n  await b.signUp(\"other@example.com\");\n  const theirs = await b.go(\"/app\");\n  assert.doesNotMatch(theirs.html, /Only mine/);\n  const steal = await b.go(\"/app/notes/\" + id + \"/delete\", { method: \"POST\", form: { _csrf: b.token(theirs.html) } });\n  assert.equal(steal.status, 404);\n  assert.match((await a.go(\"/app\")).html, /Only mine/);\n});\n\ntest(\"resets a password with a one-time link and signs out every old session\", async () => {\n  const a = browser();\n  await a.signUp(\"reset@example.com\", \"the first long password\");\n  const page = await a.go(\"/reset\");\n  const unknown = await a.go(\"/reset\", { method: \"POST\", form: { _csrf: a.token(page.html), email: \"ghost@example.com\" } });\n  assert.match(unknown.html, /If that email has an account/);\n  await a.go(\"/reset\", { method: \"POST\", form: { _csrf: a.token(page.html), email: \"reset@example.com\" } });\n  const link = resetLinks.find((l) => l.email === \"reset@example.com\").path;\n\n  const b = browser();\n  const form = await b.go(link);\n  const done = await b.go(link, { method: \"POST\", form: { _csrf: b.token(form.html), password: \"a brand new long password\" } });\n  assert.equal(done.status, 303);\n  // The old session was signed out, and the link doesn't work twice.\n  assert.equal((await a.go(\"/app\")).status, 303);\n  const again = await b.go(link, { method: \"POST\", form: { _csrf: b.token(form.html), password: \"another long password!\" } });\n  assert.match(again.html, /expired or was already used/);\n  assert.equal((await browser().signIn(\"reset@example.com\", \"a brand new long password\")).status, 303);\n});\n\ntest(\"signs out, and deletes an account with all its notes\", async () => {\n  const a = browser();\n  await a.signUp(\"leaving@example.com\", \"a long goodbye password\");\n  await a.addNote(\"Soon gone\");\n  const account = await a.go(\"/account\");\n  const deleted = await a.go(\"/account/delete\", { method: \"POST\", form: { _csrf: a.token(account.html), password: \"a long goodbye password\" } });\n  assert.equal(deleted.location, \"/sign-in?done=deleted\");\n  assert.equal((await a.go(\"/app\")).status, 303);\n  const saved = await readFile(join(dir, \"fieldnote.json\"), \"utf8\");\n  assert.doesNotMatch(saved, /Soon gone|leaving@example\\.com/);\n});\n" },
];

